import type { ReactNode } from 'react'
import { Navigate } from 'react-router-dom'
import { useAuth } from './AuthContext'

interface ProtectedRouteProps {
  children: ReactNode
}

export function ProtectedRoute({ children }: ProtectedRouteProps) {
  const { loading, isAuthenticated } = useAuth()

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-3">
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-primary-200 border-t-primary-600" />
          <p className="text-sm text-slate-500">جاري التحميل...</p>
        </div>
      </div>
    )
  }

  if (!isAuthenticated) {
    return <Navigate to="/login" replace />
  }

  return <>{children}</>
}

export function PublicOnlyRoute({ children }: ProtectedRouteProps) {
  const { loading, isAuthenticated } = useAuth()

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="h-8 w-8 animate-spin rounded-full border-2 border-primary-200 border-t-primary-600" />
      </div>
    )
  }

  if (isAuthenticated) {
    return <Navigate to="/" replace />
  }

  return <>{children}</>
}

import { supabase } from '../supabaseClient'
import { auditLogRepository } from '../repositories/auditLogRepository'
import { preferenceRepository } from '../repositories/preferenceRepository'

export interface SignUpResult {
  success: boolean
  error: string | null
  needsVerification: boolean
}

export interface SignInResult {
  success: boolean
  error: string | null
}

export interface ForgotPasswordResult {
  success: boolean
  error: string | null
}

export const authService = {
  async signUp(email: string, password: string): Promise<SignUpResult> {
    const { data, error } = await supabase.auth.signUp({ email, password })
    if (error) {
      return { success: false, error: error.message, needsVerification: false }
    }
    if (data.user && !data.session) {
      return { success: true, error: null, needsVerification: true }
    }
    if (data.user && data.session) {
      try {
        await preferenceRepository.upsert({ preferred_currency: 'SAR', preferred_language: 'ar' })
        await auditLogRepository.create({ action: 'sign_up', entity_type: 'auth' })
      } catch { }
    }
    return { success: true, error: null, needsVerification: false }
  },

  async signIn(email: string, password: string): Promise<SignInResult> {
    const { error } = await supabase.auth.signInWithPassword({ email, password })
    if (error) {
      return { success: false, error: error.message }
    }
    try {
      await auditLogRepository.create({ action: 'sign_in', entity_type: 'auth' })
    } catch { }
    return { success: true, error: null }
  },

  async signOut(): Promise<void> {
    try {
      await auditLogRepository.create({ action: 'sign_out', entity_type: 'auth' })
    } catch { }
    await supabase.auth.signOut()
  },

  async resetPassword(email: string): Promise<ForgotPasswordResult> {
    const { error } = await supabase.auth.resetPasswordForEmail(email)
    if (error) {
      return { success: false, error: error.message }
    }
    return { success: true, error: null }
  },

  async resendVerification(email: string): Promise<{ success: boolean; error: string | null }> {
    const { error } = await supabase.auth.resend({ type: 'signup', email })
    if (error) {
      return { success: false, error: error.message }
    }
    return { success: true, error: null }
  },

  async getSession() {
    const { data } = await supabase.auth.getSession()
    return data.session
  },

  async getCurrentUser() {
    const { data } = await supabase.auth.getUser()
    return data.user
  },
}

export interface AuthError {
  field: 'email' | 'password' | 'confirmPassword' | 'general'
  message: string
}

export function validateEmail(email: string): string | null {
  if (!email.trim()) return 'البريد الإلكتروني مطلوب'
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  if (!re.test(email)) return 'صيغة البريد الإلكتروني غير صحيحة'
  return null
}

export function validatePassword(password: string): string | null {
  if (!password) return 'كلمة المرور مطلوبة'
  if (password.length < 6) return 'كلمة المرور يجب أن تكون 6 أحرف على الأقل'
  return null
}

export function validateSignUpForm(email: string, password: string, confirmPassword: string): AuthError[] {
  const errors: AuthError[] = []
  const emailError = validateEmail(email)
  if (emailError) errors.push({ field: 'email', message: emailError })
  const passwordError = validatePassword(password)
  if (passwordError) errors.push({ field: 'password', message: passwordError })
  if (password !== confirmPassword) {
    errors.push({ field: 'confirmPassword', message: 'كلمتا المرور غير متطابقتين' })
  }
  return errors
}

export function validateSignInForm(email: string, password: string): AuthError[] {
  const errors: AuthError[] = []
  const emailError = validateEmail(email)
  if (emailError) errors.push({ field: 'email', message: emailError })
  const passwordError = validatePassword(password)
  if (passwordError) errors.push({ field: 'password', message: passwordError })
  return errors
}

export function mapAuthErrorMessage(error: unknown): string {
  const msg = typeof error === 'string'
    ? error
    : (error && typeof error === 'object' && 'message' in error)
      ? (error as { message: string }).message
      : ''
  if (!msg) return 'حدث خطأ غير متوقع'
  if (msg.includes('Invalid login credentials')) return 'بيانات الدخول غير صحيحة'
  if (msg.includes('User already registered')) return 'هذا البريد مسجل بالفعل'
  if (msg.includes('Email not confirmed')) return 'البريد الإلكتروني غير مؤكد'
  if (msg.includes('Password should be at least')) return 'كلمة المرور قصيرة جداً'
  if (msg.includes('rate limit')) return 'محاولات كثيرة، حاول لاحقاً'
  return msg
}

export interface BookingCapabilities {
  supportsRedirect: boolean
  supportsEmbeddedCheckout: boolean
  supportsMerchantBooking: boolean
  supportsCancellation: boolean
  supportsConfirmationImport: boolean
  supportsDeepLink: boolean
  bookingUrlAvailable: boolean
}

export function defaultBookingCapabilities(): BookingCapabilities {
  return {
    supportsRedirect: false,
    supportsEmbeddedCheckout: false,
    supportsMerchantBooking: false,
    supportsCancellation: false,
    supportsConfirmationImport: false,
    supportsDeepLink: false,
    bookingUrlAvailable: false,
  }
}

export function redirectOnlyCapabilities(): BookingCapabilities {
  return {
    ...defaultBookingCapabilities(),
    supportsRedirect: true,
    supportsDeepLink: true,
  }
}

export function redirectWithCancellationCapabilities(): BookingCapabilities {
  return {
    ...redirectOnlyCapabilities(),
    supportsCancellation: true,
  }
}

export function redirectWithCancellationAndImportCapabilities(): BookingCapabilities {
  return {
    ...redirectWithCancellationCapabilities(),
    supportsConfirmationImport: true,
  }
}

import type {
  BookingSession,
  BookingItem,
  BookingStatus,
  BookingMode,
  BookingItemType,
  ProviderReference,
} from './bookingTypes'
import { RAHHAL_BOOKING_FEE } from './bookingTypes'
import type { BookingCapabilities } from './bookingCapabilities'
import {
  redirectWithCancellationCapabilities,
  redirectWithCancellationAndImportCapabilities,
  defaultBookingCapabilities,
} from './bookingCapabilities'
import type { BookingAction } from './bookingAction'
import { redirectBookingAction, disabledBookingAction, isSafeBookingUrl } from './bookingAction'

export interface CreateBookingSessionInput {
  userId: string
  travelSessionId: string | null
  currency: string
  expiresAt: string
}

export interface AddBookingItemInput {
  type: BookingItemType
  providerId: string
  providerName: string
  providerOfferId: string
  title: string
  price: number
  currency: string
  bookingUrl: string
  expiresAt: string | null
  travelerSummary: string
  metadata: Record<string, unknown>
  capabilities?: BookingCapabilities
}

export interface BookingSummary {
  subtotal: number
  fees: number
  total: number
  currency: string
  itemCount: number
}

export interface BookingReadinessResult {
  ready: boolean
  status: BookingStatus
  warnings: string[]
}

function generateId(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID()
  }
  return `bk_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`
}

function nowIso(): string {
  return new Date().toISOString()
}

export function deriveBookingCapabilities(
  _itemType: BookingItemType,
  bookingUrl: string,
  cancellationAvailable: boolean,
): BookingCapabilities {
  const hasUrl = !!bookingUrl && isSafeBookingUrl(bookingUrl)
  if (!hasUrl) {
    return defaultBookingCapabilities()
  }
  if (cancellationAvailable) {
    return redirectWithCancellationAndImportCapabilities()
  }
  return redirectWithCancellationCapabilities()
}

function isItemExpired(item: BookingItem): boolean {
  if (!item.expiresAt) return false
  return new Date(item.expiresAt).getTime() < Date.now()
}

function isSessionExpired(session: BookingSession): boolean {
  return new Date(session.expiresAt).getTime() < Date.now()
}

export class BookingOrchestrator {
  private sessions: Map<string, BookingSession> = new Map()
  private lastError: string | null = null

  getLastError(): string | null {
    return this.lastError
  }

  createBookingSession(input: CreateBookingSessionInput): BookingSession {
    const now = nowIso()
    const session: BookingSession = {
      id: generateId(),
      userId: input.userId,
      travelSessionId: input.travelSessionId,
      status: 'draft',
      items: [],
      subtotal: 0,
      fees: RAHHAL_BOOKING_FEE,
      total: 0,
      currency: input.currency,
      selectedBookingMode: 'redirect',
      providerReferences: [],
      createdAt: now,
      updatedAt: now,
      expiresAt: input.expiresAt,
      redirectedAt: null,
      confirmedAt: null,
    }
    this.sessions.set(session.id, session)
    this.lastError = null
    return this.cloneSession(session)
  }

  getBookingSession(sessionId: string): BookingSession | null {
    const session = this.sessions.get(sessionId)
    if (!session) return null
    return this.cloneSession(session)
  }

  addBookingItem(sessionId: string, input: AddBookingItemInput): { session: BookingSession | null; error: string | null } {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return { session: null, error: 'Session not found' }
    }
    if (isSessionExpired(session)) {
      session.status = 'expired'
      this.lastError = 'Session expired'
      return { session: this.cloneSession(session), error: 'Session expired' }
    }

    const duplicate = session.items.find(
      item =>
        item.type === input.type &&
        item.providerId === input.providerId &&
        item.providerOfferId === input.providerOfferId,
    )
    if (duplicate) {
      this.lastError = 'Duplicate booking item'
      return { session: this.cloneSession(session), error: 'Duplicate booking item' }
    }

    if (input.currency !== session.currency) {
      this.lastError = `Currency mismatch: item ${input.currency} vs session ${session.currency}`
      return { session: this.cloneSession(session), error: 'Currency mismatch' }
    }

    const caps = input.capabilities ?? deriveBookingCapabilities(input.type, input.bookingUrl, false)
    const mode: BookingMode = caps.supportsRedirect ? 'redirect' : 'redirect'

    const item: BookingItem = {
      id: generateId(),
      type: input.type,
      providerId: input.providerId,
      providerName: input.providerName,
      providerOfferId: input.providerOfferId,
      title: input.title,
      price: input.price,
      currency: input.currency,
      bookingUrl: input.bookingUrl,
      bookingMode: mode,
      expiresAt: input.expiresAt,
      travelerSummary: input.travelerSummary,
      selectedAt: nowIso(),
      metadata: input.metadata,
    }

    session.items.push(item)
    if (session.status === 'draft') {
      session.status = 'selected'
    }
    this.recalculate(session)
    session.updatedAt = nowIso()
    this.lastError = null
    return { session: this.cloneSession(session), error: null }
  }

  removeBookingItem(sessionId: string, itemId: string): BookingSession | null {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return null
    }
    session.items = session.items.filter(item => item.id !== itemId)
    session.providerReferences = session.providerReferences.filter(
      ref => !session.items.some(item => item.providerId === ref.providerId),
    )
    if (session.items.length === 0 && session.status !== 'cancelled' && session.status !== 'expired') {
      session.status = 'draft'
    }
    this.recalculate(session)
    session.updatedAt = nowIso()
    this.lastError = null
    return this.cloneSession(session)
  }

  updateBookingItem(sessionId: string, itemId: string, updates: Partial<Pick<BookingItem, 'bookingUrl' | 'price' | 'expiresAt' | 'metadata'>>): BookingSession | null {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return null
    }
    const item = session.items.find(i => i.id === itemId)
    if (!item) {
      this.lastError = 'Item not found'
      return null
    }
    if (updates.bookingUrl !== undefined) item.bookingUrl = updates.bookingUrl
    if (updates.price !== undefined) item.price = updates.price
    if (updates.expiresAt !== undefined) item.expiresAt = updates.expiresAt
    if (updates.metadata !== undefined) item.metadata = { ...item.metadata, ...updates.metadata }
    this.recalculate(session)
    session.updatedAt = nowIso()
    this.lastError = null
    return this.cloneSession(session)
  }

  calculateBookingSummary(sessionId: string): BookingSummary | null {
    const session = this.sessions.get(sessionId)
    if (!session) return null
    return {
      subtotal: session.subtotal,
      fees: session.fees,
      total: session.total,
      currency: session.currency,
      itemCount: session.items.length,
    }
  }

  determineBookingMode(sessionId: string): BookingMode {
    const session = this.sessions.get(sessionId)
    if (!session) return 'redirect'
    return 'redirect'
  }

  validateBookingReadiness(sessionId: string): BookingReadinessResult {
    const session = this.sessions.get(sessionId)
    if (!session) {
      return { ready: false, status: 'draft', warnings: ['Session not found'] }
    }

    const warnings: string[] = []

    if (isSessionExpired(session)) {
      session.status = 'expired'
      return { ready: false, status: 'expired', warnings: ['Session has expired'] }
    }

    if (session.status === 'cancelled') {
      return { ready: false, status: 'cancelled', warnings: ['Session is cancelled'] }
    }

    if (session.items.length === 0) {
      return { ready: false, status: session.status, warnings: ['No items in session'] }
    }

    const expiredItems = session.items.filter(isItemExpired)
    if (expiredItems.length > 0) {
      warnings.push(`${expiredItems.length} item(s) have expired`)
    }

    const itemsWithoutUrl = session.items.filter(item => !item.bookingUrl)
    if (itemsWithoutUrl.length > 0) {
      warnings.push(`${itemsWithoutUrl.length} item(s) missing booking URL`)
    }

    const currencies = new Set(session.items.map(item => item.currency))
    if (currencies.size > 1 || !currencies.has(session.currency)) {
      warnings.push('Currency mismatch detected')
    }

    const ready = warnings.length === 0
    if (ready && session.status !== 'redirected') {
      session.status = 'ready_to_redirect'
    }

    session.updatedAt = nowIso()
    return { ready, status: session.status, warnings }
  }

  prepareRedirect(sessionId: string): BookingAction | null {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return null
    }

    if (isSessionExpired(session)) {
      session.status = 'expired'
      this.lastError = 'Session expired'
      return disabledBookingAction('redirect', '', '', 'session_expired')
    }

    if (session.status === 'cancelled') {
      this.lastError = 'Session cancelled'
      return disabledBookingAction('redirect', '', '', 'session_cancelled')
    }

    if (session.items.length === 0) {
      this.lastError = 'No items'
      return disabledBookingAction('redirect', '', '', 'no_items')
    }

    const firstItem = session.items[0]
    const readiness = this.validateBookingReadiness(sessionId)
    if (!readiness.ready) {
      this.lastError = readiness.warnings.join('; ')
      if (!firstItem.bookingUrl) {
        return disabledBookingAction('redirect', firstItem.providerId, firstItem.providerName, 'redirect_url_missing', readiness.warnings)
      }
      if (!isSafeBookingUrl(firstItem.bookingUrl)) {
        return disabledBookingAction('redirect', firstItem.providerId, firstItem.providerName, 'redirect_invalid_url', readiness.warnings)
      }
    }

    const action = redirectBookingAction(
      firstItem.providerId,
      firstItem.providerName,
      firstItem.bookingUrl,
      firstItem.expiresAt,
      readiness.warnings,
    )

    if (action.allowed) {
      session.status = 'ready_to_redirect'
      session.updatedAt = nowIso()
    }

    this.lastError = null
    return action
  }

  markRedirected(sessionId: string): BookingSession | null {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return null
    }
    if (session.status !== 'ready_to_redirect' && session.status !== 'selected') {
      this.lastError = `Cannot redirect from status: ${session.status}`
      return this.cloneSession(session)
    }
    session.status = 'redirected'
    session.redirectedAt = nowIso()
    session.updatedAt = nowIso()

    const providers = new Map<string, ProviderReference>()
    for (const item of session.items) {
      if (!providers.has(item.providerId)) {
        providers.set(item.providerId, {
          providerId: item.providerId,
          providerName: item.providerName,
          providerBookingReference: null,
          redirectUrl: item.bookingUrl,
        })
      }
    }
    session.providerReferences = Array.from(providers.values())

    this.lastError = null
    return this.cloneSession(session)
  }

  expireBookingSession(sessionId: string): BookingSession | null {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return null
    }
    if (session.status === 'confirmed' || session.status === 'redirected') {
      this.lastError = `Cannot expire session in status: ${session.status}`
      return this.cloneSession(session)
    }
    session.status = 'expired'
    session.updatedAt = nowIso()
    this.lastError = null
    return this.cloneSession(session)
  }

  cancelBookingSession(sessionId: string): BookingSession | null {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return null
    }
    if (session.status === 'confirmed') {
      this.lastError = 'Cannot cancel confirmed session'
      return this.cloneSession(session)
    }
    session.status = 'cancelled'
    session.updatedAt = nowIso()
    this.lastError = null
    return this.cloneSession(session)
  }

  addProviderReference(sessionId: string, providerId: string, reference: string): BookingSession | null {
    const session = this.sessions.get(sessionId)
    if (!session) {
      this.lastError = 'Session not found'
      return null
    }
    const ref = session.providerReferences.find(r => r.providerId === providerId)
    if (ref) {
      ref.providerBookingReference = reference
    } else {
      session.providerReferences.push({
        providerId,
        providerName: '',
        providerBookingReference: reference,
        redirectUrl: null,
      })
    }
    session.status = 'pending_provider_confirmation'
    session.updatedAt = nowIso()
    this.lastError = null
    return this.cloneSession(session)
  }

  getAllSessions(): BookingSession[] {
    return Array.from(this.sessions.values()).map(s => this.cloneSession(s))
  }

  getSessionsByUser(userId: string): BookingSession[] {
    return Array.from(this.sessions.values())
      .filter(s => s.userId === userId)
      .map(s => this.cloneSession(s))
  }

  private recalculate(session: BookingSession): void {
    session.subtotal = session.items.reduce((sum, item) => sum + item.price, 0)
    session.fees = RAHHAL_BOOKING_FEE
    session.total = session.subtotal + session.fees
  }

  private cloneSession(session: BookingSession): BookingSession {
    return {
      ...session,
      items: session.items.map(item => ({ ...item, metadata: { ...item.metadata } })),
      providerReferences: session.providerReferences.map(ref => ({ ...ref })),
    }
  }

  _internalGetSession(sessionId: string): BookingSession | undefined {
    return this.sessions.get(sessionId)
  }
}

let cachedOrchestrator: BookingOrchestrator | null = null

export function getBookingOrchestrator(): BookingOrchestrator {
  if (cachedOrchestrator) return cachedOrchestrator
  cachedOrchestrator = new BookingOrchestrator()
  return cachedOrchestrator
}

export function resetBookingOrchestrator(): void {
  cachedOrchestrator = null
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useAuth } from '../auth/AuthContext'
import { sessionRepository } from '../repositories/sessionRepository'
import {
  createEmptyTravelSession,
  mergeTravelSession,
  type TravelSession,
} from '../../utils/travelSession'

export function useSessionPersistence() {
  const { user, loading: authLoading } = useAuth()
  const [session, setSessionState] = useState<TravelSession>(createEmptyTravelSession())
  const [sessionId, setSessionId] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    if (authLoading) return
    if (!user) {
      setSessionState(createEmptyTravelSession())
      setSessionId(null)
      setLoading(false)
      return
    }
    (async () => {
      try {
        const rows = await sessionRepository.listByUser(1)
        if (rows.length > 0) {
          const latest = rows[0]
          const restored = sessionRepository.dataToSession(latest.session_data)
          setSessionState(restored)
          setSessionId(latest.id)
        } else {
          setSessionState(createEmptyTravelSession())
          setSessionId(null)
        }
      } catch {
        setSessionState(createEmptyTravelSession())
      } finally {
        setLoading(false)
      }
    })()
  }, [user, authLoading])

  const saveSession = useCallback((updated: TravelSession) => {
    setSessionState(updated)
    if (!user) return
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current)
    saveTimerRef.current = setTimeout(async () => {
      try {
        if (sessionId) {
          await sessionRepository.update(sessionId, updated)
        } else if (updated.destination || updated.departureCity || updated.adults) {
          const row = await sessionRepository.create(updated)
          if (row) setSessionId(row.id)
        }
      } catch { }
    }, 800)
  }, [user, sessionId])

  const mergeSession = useCallback((newData: string | Partial<TravelSession>): TravelSession => {
    const updated = mergeTravelSession(session, newData)
    saveSession(updated)
    return updated
  }, [session, saveSession])

  const clearSession = useCallback(() => {
    setSessionState(createEmptyTravelSession())
    setSessionId(null)
  }, [])

  return {
    session,
    sessionId,
    loading,
    saveSession,
    mergeSession,
    clearSession,
    setSession: setSessionState,
  }
}

export type LockStatus = 'active' | 'released' | 'expired'

export interface BookingLock {
  id: string
  orderId: string
  userId: string
  status: LockStatus
  lockToken: string
  createdAt: string
  expiresAt: string
  releasedAt: string | null
}

const LOCK_TTL_MS = 5 * 60 * 1000

const locks: Map<string, BookingLock> = new Map()
const orderLocks: Map<string, string> = new Map()

function generateId(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID()
  }
  return `lock_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`
}

function generateToken(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID()
  }
  return `tok_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`
}

export function acquireLock(orderId: string, userId: string): BookingLock | null {
  const existingLockId = orderLocks.get(orderId)
  if (existingLockId) {
    const existing = locks.get(existingLockId)
    if (existing && existing.status === 'active' && !isLockExpired(existing)) {
      return null
    }
    if (existing) {
      existing.status = 'expired'
    }
    orderLocks.delete(orderId)
  }

  const now = Date.now()
  const lock: BookingLock = {
    id: generateId(),
    orderId,
    userId,
    status: 'active',
    lockToken: generateToken(),
    createdAt: new Date(now).toISOString(),
    expiresAt: new Date(now + LOCK_TTL_MS).toISOString(),
    releasedAt: null,
  }
  locks.set(lock.id, lock)
  orderLocks.set(orderId, lock.id)
  return { ...lock }
}

export function releaseLock(orderId: string, lockToken: string): boolean {
  const lockId = orderLocks.get(orderId)
  if (!lockId) return false
  const lock = locks.get(lockId)
  if (!lock || lock.lockToken !== lockToken) return false
  lock.status = 'released'
  lock.releasedAt = new Date().toISOString()
  orderLocks.delete(orderId)
  return true
}

export function verifyLock(orderId: string, lockToken: string): boolean {
  const lockId = orderLocks.get(orderId)
  if (!lockId) return false
  const lock = locks.get(lockId)
  if (!lock || lock.lockToken !== lockToken) return false
  if (lock.status !== 'active' || isLockExpired(lock)) {
    lock.status = 'expired'
    orderLocks.delete(orderId)
    return false
  }
  return true
}

export function getLock(orderId: string): BookingLock | null {
  const lockId = orderLocks.get(orderId)
  if (!lockId) return null
  const lock = locks.get(lockId)
  if (!lock) return null
  if (lock.status === 'active' && isLockExpired(lock)) {
    lock.status = 'expired'
    orderLocks.delete(orderId)
    return { ...lock }
  }
  return { ...lock }
}

export function clearAllLocks(): void {
  locks.clear()
  orderLocks.clear()
}

function isLockExpired(lock: BookingLock): boolean {
  return new Date(lock.expiresAt).getTime() < Date.now()
}

import type {
  RahhalOrder,
  CheckoutCart,
  CheckoutItem,
  TravelerInfo,
} from './checkoutTypes'
import type {
  PaymentSession,
} from './paymentTypes'
import type { PaymentProvider } from './paymentProvider'
import {
  createOrder,
  getOrder,
  updateOrderStatus,
  attachPaymentSession,
  markOrderPaid,
  markOrderConfirmed,
  buildCart,
  generateInvoiceNumber,
  generateItineraryId,
} from './orderManager'
import { validateCoupon } from './couponValidator'
import {
  acquireLock,
  releaseLock,
  verifyLock,
  getLock,
} from './bookingLock'
import { generateInvoice } from './invoiceGenerator'
import { generateItinerary } from './itineraryGenerator'
import type { Invoice } from './invoiceGenerator'
import type { Itinerary } from './itineraryGenerator'

export interface CheckoutInitInput {
  userId: string
  travelSessionId: string | null
  items: CheckoutItem[]
  currency: string
  travelers: TravelerInfo[]
  couponCode: string | null
}

export interface CheckoutSession {
  order: RahhalOrder
  cart: CheckoutCart
  lockToken: string | null
  paymentSession: PaymentSession | null
}

export interface PaymentExecutionResult {
  success: boolean
  order: RahhalOrder | null
  paymentSession: PaymentSession | null
  invoice: Invoice | null
  itinerary: Itinerary | null
  message: string
}

export class CheckoutOrchestrator {
  private provider: PaymentProvider
  private paymentSessions: Map<string, PaymentSession> = new Map()

  constructor(provider: PaymentProvider) {
    this.provider = provider
  }

  initiateCheckout(input: CheckoutInitInput): CheckoutSession {
    let discountAmount = 0
    if (input.couponCode) {
      const tempCart = buildCart(input.items, input.currency, null, 0)
      const couponResult = validateCoupon(input.couponCode, tempCart)
      if (couponResult.valid) {
        discountAmount = couponResult.discountAmount
      }
    }

    const cart = buildCart(input.items, input.currency, input.couponCode, discountAmount)
    const order = createOrder({
      userId: input.userId,
      travelSessionId: input.travelSessionId,
      cart,
      travelers: input.travelers,
      couponCode: input.couponCode,
      discountAmount,
    })

    const lock = acquireLock(order.id, input.userId)

    return {
      order,
      cart,
      lockToken: lock?.lockToken ?? null,
      paymentSession: null,
    }
  }

  async createPaymentSession(
    orderId: string,
    customerEmail: string | null,
    customerName: string | null,
    returnUrl: string,
  ): Promise<PaymentExecutionResult> {
    const order = getOrder(orderId)
    if (!order) {
      return this.failure('Order not found', null)
    }

    const result = await this.provider.createPaymentSession({
      orderId: order.id,
      orderNumber: order.orderNumber,
      amount: order.cart.total,
      currency: order.cart.currency,
      description: `Rahhal Order ${order.orderNumber}`,
      customerEmail,
      customerName,
      returnUrl,
      metadata: { orderNumber: order.orderNumber, bookingNumber: order.bookingNumber },
    })

    if (!result.success) {
      updateOrderStatus(orderId, 'failed')
      return this.failure(result.message, null)
    }

    const paymentSession: PaymentSession = {
      id: result.paymentSessionId,
      orderId: order.id,
      orderNumber: order.orderNumber,
      providerId: result.providerId,
      status: result.status,
      amount: order.cart.total,
      currency: order.cart.currency,
      paymentMethod: null,
      providerReference: result.providerReference,
      authorizationCode: result.authorizationCode,
      transactionId: result.transactionId,
      redirectUrl: result.redirectUrl,
      description: `Rahhal Order ${order.orderNumber}`,
      customerEmail,
      customerName,
      metadata: result.metadata,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      paidAt: null,
      expiresAt: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
    }

    this.paymentSessions.set(paymentSession.id, paymentSession)
    attachPaymentSession(orderId, paymentSession)
    updateOrderStatus(orderId, 'pending_payment')

    return {
      success: true,
      order: getOrder(orderId),
      paymentSession,
      invoice: null,
      itinerary: null,
      message: 'Payment session created',
    }
  }

  async executePayment(orderId: string, lockToken: string): Promise<PaymentExecutionResult> {
    const order = getOrder(orderId)
    if (!order) {
      return this.failure('Order not found', null)
    }

    if (!verifyLock(orderId, lockToken)) {
      return this.failure('Booking lock is invalid or expired. Preventing duplicate payment.', order)
    }

    if (!order.paymentSessionId) {
      return this.failure('No payment session attached to order', order)
    }

    const paymentSession = this.paymentSessions.get(order.paymentSessionId)
    if (!paymentSession) {
      return this.failure('Payment session not found', order)
    }

    if (paymentSession.status === 'paid') {
      return this.failure('Payment already completed', order)
    }

    const authResult = await this.provider.authorizePayment(paymentSession.id)
    if (!authResult.success) {
      paymentSession.status = 'failed'
      paymentSession.updatedAt = new Date().toISOString()
      updateOrderStatus(orderId, 'failed')
      return this.failure(authResult.message, order)
    }

    paymentSession.status = authResult.status
    paymentSession.authorizationCode = authResult.authorizationCode
    paymentSession.transactionId = authResult.transactionId
    paymentSession.updatedAt = new Date().toISOString()

    const captureResult = await this.provider.capturePayment(paymentSession.id)
    if (!captureResult.success) {
      paymentSession.status = 'failed'
      paymentSession.updatedAt = new Date().toISOString()
      updateOrderStatus(orderId, 'failed')
      return this.failure(captureResult.message, order)
    }

    paymentSession.status = 'paid'
    paymentSession.paidAt = captureResult.paidAt ?? new Date().toISOString()
    paymentSession.updatedAt = new Date().toISOString()

    const invoiceNumber = generateInvoiceNumber(order)
    markOrderPaid(orderId, invoiceNumber)

    const itineraryId = generateItineraryId(order)
    markOrderConfirmed(orderId, itineraryId)

    releaseLock(orderId, lockToken)

    const updatedOrder = getOrder(orderId)!
    const invoice = generateInvoice(updatedOrder)
    const itinerary = generateItinerary(updatedOrder)

    return {
      success: true,
      order: updatedOrder,
      paymentSession,
      invoice,
      itinerary,
      message: 'Payment successful, order confirmed, invoice and itinerary generated',
    }
  }

  async retryPayment(orderId: string): Promise<PaymentExecutionResult> {
    const order = getOrder(orderId)
    if (!order) {
      return this.failure('Order not found', null)
    }
    if (order.status === 'paid' || order.status === 'confirmed') {
      return this.failure('Order is already paid', order)
    }

    const lock = acquireLock(order.id, order.userId)
    if (!lock) {
      return this.failure('Cannot acquire lock for retry. Another payment in progress.', order)
    }

    return this.createPaymentSession(orderId, null, null, '')
  }

  cancelCheckout(orderId: string, lockToken: string | null): PaymentExecutionResult {
    const order = getOrder(orderId)
    if (!order) {
      return this.failure('Order not found', null)
    }

    if (lockToken) {
      releaseLock(orderId, lockToken)
    }

    updateOrderStatus(orderId, 'cancelled')
    return {
      success: true,
      order: getOrder(orderId),
      paymentSession: null,
      invoice: null,
      itinerary: null,
      message: 'Checkout cancelled',
    }
  }

  recoverAbandonedCheckout(orderId: string): PaymentExecutionResult {
    const order = getOrder(orderId)
    if (!order) {
      return this.failure('Order not found', null)
    }

    if (order.status === 'paid' || order.status === 'confirmed') {
      return this.failure('Order is already completed', order)
    }

    if (order.status === 'cancelled' || order.status === 'refunded') {
      return this.failure('Cannot recover a cancelled or refunded order', order)
    }

    const lock = getLock(orderId)
    if (lock && lock.status === 'active') {
      return {
        success: true,
        order,
        paymentSession: order.paymentSessionId ? this.paymentSessions.get(order.paymentSessionId) ?? null : null,
        invoice: null,
        itinerary: null,
        message: 'Checkout resumed — payment in progress',
      }
    }

    const newLock = acquireLock(order.id, order.userId)
    void newLock
    return {
      success: true,
      order,
      paymentSession: order.paymentSessionId ? this.paymentSessions.get(order.paymentSessionId) ?? null : null,
      invoice: null,
      itinerary: null,
      message: 'Abandoned checkout recovered. New lock acquired.',
    }
  }

  getPaymentSession(paymentSessionId: string): PaymentSession | null {
    return this.paymentSessions.get(paymentSessionId) ?? null
  }

  getOrder(orderId: string): RahhalOrder | null {
    return getOrder(orderId)
  }

  private failure(message: string, order: RahhalOrder | null): PaymentExecutionResult {
    return {
      success: false,
      order,
      paymentSession: null,
      invoice: null,
      itinerary: null,
      message,
    }
  }
}

let cachedOrchestrator: CheckoutOrchestrator | null = null

export function getCheckoutOrchestrator(provider: PaymentProvider): CheckoutOrchestrator {
  if (cachedOrchestrator) return cachedOrchestrator
  cachedOrchestrator = new CheckoutOrchestrator(provider)
  return cachedOrchestrator
}

export function resetCheckoutOrchestrator(): void {
  cachedOrchestrator = null
}

import type { Coupon, CouponValidationResult, CheckoutCart } from './checkoutTypes'

const COUPONS: Map<string, Coupon> = new Map()

export function registerCoupon(coupon: Coupon): void {
  COUPONS.set(coupon.code.toUpperCase(), coupon)
}

export function getCoupon(code: string): Coupon | null {
  return COUPONS.get(code.toUpperCase()) ?? null
}

export function clearCoupons(): void {
  COUPONS.clear()
}

export function validateCoupon(
  code: string,
  cart: CheckoutCart,
): CouponValidationResult {
  const coupon = getCoupon(code)
  if (!coupon) {
    return { valid: false, coupon: null, discountAmount: 0, message: 'Coupon code not found' }
  }
  if (!coupon.active) {
    return { valid: false, coupon, discountAmount: 0, message: 'Coupon is no longer active' }
  }
  if (coupon.expiresAt && new Date(coupon.expiresAt).getTime() < Date.now()) {
    return { valid: false, coupon, discountAmount: 0, message: 'Coupon has expired' }
  }
  if (coupon.minOrderAmount && cart.subtotal < coupon.minOrderAmount) {
    return {
      valid: false,
      coupon,
      discountAmount: 0,
      message: `Minimum order amount is ${coupon.minOrderAmount} ${cart.currency}`,
    }
  }

  let discount = 0
  if (coupon.type === 'percentage') {
    discount = Math.round(cart.subtotal * (coupon.value / 100))
    if (coupon.maxDiscount) {
      discount = Math.min(discount, coupon.maxDiscount)
    }
  } else {
    discount = coupon.value
    if (coupon.currency && coupon.currency !== cart.currency) {
      return {
        valid: false,
        coupon,
        discountAmount: 0,
        message: `Coupon currency (${coupon.currency}) does not match cart (${cart.currency})`,
      }
    }
  }

  discount = Math.min(discount, cart.subtotal)

  return {
    valid: true,
    coupon,
    discountAmount: discount,
    message: `Coupon applied: ${coupon.description}`,
  }
}

